test-case.test:
(: FTContains-1: Basic syntax :)
declare variable $input-context external;
$input-context//metadata/title contains text "Usability"

(: FTContains-pred1: Basic syntax: contains text in a predicate :)
declare variable $input-context external;
$input-context//metadata/title[. contains text "Usability"]

(: FTContains-predcomp1: contains text in a predicate with a comparison operator :)
declare variable $input-context external;
$input-context//metadata/title[. contains text "Usability" eq fn:false()]

(: FTContains-comp1: contains text higher precedence than other comparison operators :)
declare variable $input-context external;
$input-context//metadata/title contains text "Usability" eq fn:false()

(: FTContains-comp2: contains text higher precedence than other comparison operators :)
declare variable $input-context external;
$input-context//metadata/title contains text "Usability" ne fn:false()

(: FTContains-badcomp1: contains text higher precedence than other comparison operators :)
declare variable $input-context external;
"Smith" eq $input-context//metadata/title contains text "Usability"

declare ft-option using case sensitive;
declare variable $input-context external;
for $book in $input-context/books/book
let $cont := $book/content
where $cont contains text "Testing"
return $book

declare ft-option using case sensitive using stemming;
declare variable $input-context external;
for $book in $input-context/books/book
let $cont := $book/content
where $cont contains text "Testing"
return $book

declare ft-option using case sensitive;
declare ft-option using stemming using no wildcards;
declare variable $input-context external;
for $book in $input-context/books/book
let $cont := $book/content
where $cont contains text "Testing"
return $book

declare ft-option using case sensitive;
declare ft-option using stemming using case insensitive;
declare variable $input-context external;
for $book in $input-context/books/book
let $cont := $book/content
where $cont contains text "Testing"
return $book

declare ft-option using case sensitive;
declare default function namespace "http://example.org/functions";
declare variable $input-context external;
declare variable $x := 1;
for $book in $input-context/books/book
let $cont := $book[@number=$x]/content
where $cont contains text "Testing"
return $book

(: Note to maintainers: This query has an intentional syntax error. Do not "fix" it. :)
(: VarDecls before FTOptionDecl causes XPST0003 :)
declare variable $input-context external;
declare variable $x := 1;
declare ft-option using case sensitive;
for $book in $input-context/books/book
let $cont := $book[@number=$x]/content
where $cont contains text "Testing"
return $book
